export class SellAppBase {
  readonly key?: string;
  readonly store?: string;
  readonly baseURL: string;
  readonly options: Readonly<SellAppOptions>;
  private readonly fetch: typeof globalThis.fetch;
  private nextResponseObserver?: (response: SellAppResponse<unknown>) => void;

  constructor(options: SellAppOptions = {}) {
    this.key = options.accessToken ? undefined : options.apiKey ?? process.env.SELLAPP_API_KEY;
    this.store = options.store ?? process.env.SELLAPP_STORE;
    this.baseURL = (options.baseUrl ?? 'https://sell.app/api').replace(/\/$/, '');
    this.options = { timeout: 60_000, maxRetries: 2, ...options };
    this.fetch = options.fetch ?? globalThis.fetch;
  }

  protected setAuthHeaders(headers: Record<string, string>): void {
    if (!this.key || !this.store) {
      throw new SellAppConfigurationError(
        'apiKey and store are required (options or SELLAPP_API_KEY/SELLAPP_STORE)',
      );
    }
    headers.Authorization = `Bearer ${this.key}`;
    headers['X-STORE'] = this.store;
  }

  get<T>(path: string, options?: GetOptions): Promise<SellAppResponse<T>> {
    return this.request<T>('GET', path, undefined, options);
  }
  post<T, TBody = unknown>(path: string, body: TBody, options?: PostOptions): Promise<SellAppResponse<T>> {
    return this.request<T>('POST', path, body, options);
  }
  put<T, TBody = unknown>(path: string, body: TBody, options?: GetOptions): Promise<SellAppResponse<T>> {
    return this.request<T>('PUT', path, body, options);
  }
  patch<T, TBody = unknown>(path: string, body: TBody, options?: GetOptions): Promise<SellAppResponse<T>> {
    return this.request<T>('PATCH', path, body, options);
  }
  delete<T = void>(path: string, options?: GetOptions): Promise<SellAppResponse<T>> {
    return this.request<T>('DELETE', path, undefined, options);
  }
  deleteWithBody<TBody>(path: string, body: TBody, options?: GetOptions): Promise<SellAppResponse<void>> {
    return this.request<void>('DELETE', path, body, options);
  }

  customRequest<T = unknown>(method: string, path: string, options: GetOptions & { body?: unknown; allowCrossOrigin?: boolean } = {}): Promise<SellAppResponse<T>> {
    const absolute = new URL(path, this.baseURL + '/');
    const base = new URL(this.baseURL);
    if (absolute.origin !== base.origin && !options.allowCrossOrigin) {
      throw new SellAppConfigurationError('Cross-origin custom requests require allowCrossOrigin: true');
    }
    if (absolute.username || absolute.password || absolute.hash) {
      throw new SellAppConfigurationError('Custom request URLs cannot contain user info or fragments');
    }
    return this.request<T>(method.toUpperCase(), absolute.href, options.body, { ...options, idempotencySupported: false } as GetOptions & { idempotencySupported: boolean }, absolute.origin === base.origin);
  }

  async captureResponse<T>(operation: () => Promise<T>): Promise<SellAppResponse<T>> {
    let response: SellAppResponse<unknown> | undefined;
    const observer = (value: SellAppResponse<unknown>) => { response = value; };
    if (this.nextResponseObserver) throw new SellAppConfigurationError('A raw-response operation is already being started');
    this.nextResponseObserver = observer;
    let pending: Promise<T>;
    try { pending = operation(); }
    finally { if (this.nextResponseObserver === observer) this.nextResponseObserver = undefined; }
    const data = await pending;
    if (!response) throw new SellAppConfigurationError('The operation did not perform an API request');
    return { ...response, data };
  }

  private async request<T>(method: string, path: string, body?: unknown, options: GetOptions = {}, authenticated = true): Promise<SellAppResponse<T>> {
    const responseObserver = this.nextResponseObserver;
    this.nextResponseObserver = undefined;
    const headers: Record<string, string> = {
      Accept: 'application/json',
      'User-Agent': 'SellApp node/0.1.0',
      ...options.headers,
    };
    const contract = operationContracts.find(c => c.method === method && c.path.split('/').length === path.split('/').length && c.path.split('/').every((part, i) => part.startsWith('{') || part === path.split('/')[i]));
    const auth = contract?.authentication;
    let customerSessionUsed = false;
    for (const name of Object.keys(headers)) if (['authorization', 'x-store', 'cookie'].includes(name.toLowerCase())) delete headers[name];
    if (authenticated) {
      const session = options.customerSession ?? this.options.customerSession;
      if (!auth) this.setAuthHeaders(headers);
      else if (auth.customerSession && session) { headers.Authorization = 'Bearer ' + session; customerSessionUsed = true; }
      else if (auth.accessToken && this.options.accessToken) {
        if (auth.accessTokenRequiresStore && !this.store) throw new SellAppConfigurationError('store is required for OAuth access tokens');
        headers.Authorization = 'Bearer ' + this.options.accessToken;
        if (auth.accessTokenRequiresStore && this.store) headers['X-STORE'] = this.store;
      } else if (auth.apiKey && this.key) {
        if (auth.apiKeyRequiresStore && !this.store) throw new SellAppConfigurationError('store is required');
        headers.Authorization = 'Bearer ' + this.key;
        if (auth.apiKeyUsesStore && this.store) headers['X-STORE'] = this.store;
      } else if (auth.browserSession && this.options.browserSession) headers.Cookie = this.options.browserSession;
      else if (auth.clientBasic && this.options.clientId) {
        if (body && typeof body === 'object' && ('client_id' in body || 'client_secret' in body)) throw new SellAppConfigurationError('Use Basic credentials or body credentials, never both');
        headers.Authorization = 'Basic ' + Buffer.from(encodeURIComponent(this.options.clientId) + ':' + encodeURIComponent(this.options.clientSecret ?? '')).toString('base64');
      } else if (!auth.anonymous) throw new SellAppConfigurationError('Credentials required by this operation are missing');
    }
    if (contract?.form) options = { ...options, encoding: 'form' };
    if (contract?.multipart) options = { ...options, encoding: 'multipart' };
    if (options.extraBody && body !== undefined && (typeof body !== 'object' || body === null || Array.isArray(body))) {
      throw new SellAppConfigurationError('extraBody requires an object request body');
    }
    if (options.extraBody) body = { ...(body as Record<string, unknown>), ...options.extraBody };
    if (auth?.clientBasic && this.options.clientId && body && typeof body === 'object' && ('client_id' in body || 'client_secret' in body)) throw new SellAppConfigurationError('Use Basic credentials or body credentials, never both');
    let requestBody: BodyInit | undefined;
    if (body !== undefined) {
      try {
        if (options.encoding === 'form-data' || options.encoding === 'multipart') {
          const form = new FormData();
          for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
            if (Array.isArray(value)) for (const item of value) form.append(key, await multipartValue(item));
            else if (value !== undefined && value !== null) form.append(key, await multipartValue(value));
          }
          requestBody = form;
        } else if (options.encoding === 'form') {
          headers['Content-Type'] = 'application/x-www-form-urlencoded';
          const form = new URLSearchParams();
          for (const [key, value] of Object.entries(body as Record<string, unknown>)) {
            if (Array.isArray(value)) for (const item of value) form.append(key + '[]', String(item));
            else if (value !== undefined && value !== null) form.append(key, String(value));
          }
          requestBody = form;
        } else {
          headers['Content-Type'] = 'application/json';
          requestBody = JSON.stringify(body);
        }
      } catch (cause) {
        throw new SellAppSerializationError('Request body could not be serialized', { cause });
      }
    }
    if ('idempotencyKey' in options && options.idempotencyKey) {
      headers['Idempotency-Key'] = String(options.idempotencyKey);
    }
    const queryValues = { ...options.query, ...options.extraQuery };
    const query = Object.keys(queryValues).length ? `?${toQueryString(queryValues)}` : '';
    const operationBase = contract?.server ? (this.options.baseUrl ? new URL(this.baseURL).origin : contract.server) : this.baseURL;
    const url = /^https?:\/\//i.test(path) ? path + query : `${operationBase}${path}${query}`;
    const maxRetries = options.maxRetries ?? this.options.maxRetries ?? 2;
    if (!Number.isSafeInteger(maxRetries) || maxRetries < 0) throw new SellAppConfigurationError('maxRetries must be a nonnegative safe integer');
    const timeoutMs = options.timeout ?? this.options.timeout ?? 60_000;
    if (!Number.isFinite(timeoutMs) || timeoutMs <= 0) throw new SellAppConfigurationError('timeout must be positive and finite');
    const retryable = !customerSessionUsed && !contract?.retry.never && (['GET', 'HEAD', 'OPTIONS', 'TRACE', 'PUT', 'DELETE'].includes(method)
      || (method === 'POST' && Boolean(contract?.retry.declaredIdempotency && (options as PostOptions & { idempotencySupported?: boolean }).idempotencySupported) && Boolean((options as PostOptions).idempotencyKey?.trim())));

    for (let attempt = 0; ; attempt += 1) {
      if (options.signal?.aborted) throw new SellAppCancellationError('Request cancelled', { cause: options.signal.reason });
      const controller = new AbortController();
      const abort = () => controller.abort(options.signal?.reason);
      options.signal?.addEventListener('abort', abort, { once: true });
      const timeout = setTimeout(() => controller.abort(), timeoutMs);
      const startedAt = Date.now();
      try {
        const response = await this.fetch(url, {
          method,
          redirect: 'manual',
          headers,
          body: requestBody,
          signal: controller.signal,
        });
        if (!response.ok && retryable && attempt < maxRetries && (response.status === 408 || response.status === 409 || response.status === 429 || response.status >= 500)) {
          this.options.onRequest?.({ operationId: options.operationId, attempt: attempt + 1, durationMs: Date.now() - startedAt, status: response.status, requestId: response.headers.get('X-Request-ID') ?? undefined });
          await response.body?.cancel();
          clearTimeout(timeout);
          await waitForRetry(retryDelay(response.headers.get('Retry-After'), attempt), options.signal);
          continue;
        }
        const success = response.ok || response.status >= 300 && response.status < 400;
        const text = await response.text();
        let parsed: unknown = undefined;
        if (success && contract?.textResponse && !response.headers.get('Content-Type')?.toLowerCase().includes('json')) parsed = text;
        else if (text) {
          try { parsed = JSON.parse(text); }
          catch (cause) {
            if (success && contract?.textResponse) parsed = text;
            else if (response.ok) throw new SellAppSerializationError('Response was not valid JSON', { cause });
          }
        }
        if (!success) {
          this.options.onRequest?.({ operationId: options.operationId, attempt: attempt + 1, durationMs: Date.now() - startedAt, status: response.status, requestId: response.headers.get('X-Request-ID') ?? undefined, errorType: 'api' });
          const ErrorClass = response.status === 401 ? SellAppAuthenticationError : SellAppApiError;
          throw new ErrorClass(response.status, (parsed ?? {}) as SellAppErrorBody, response.headers.get('X-Request-ID') ?? undefined, response.headers, text);
        }
        this.options.onRequest?.({ operationId: options.operationId, attempt: attempt + 1, durationMs: Date.now() - startedAt, status: response.status, requestId: response.headers.get('X-Request-ID') ?? undefined });
        const result = { data: parsed as T, status: response.status, headers: response.headers, requestId: response.headers.get('X-Request-ID') ?? undefined };
        responseObserver?.(result);
        return result;
      } catch (error) {
        if (error instanceof SellAppApiError || error instanceof SellAppSerializationError || error instanceof SellAppTransportError) throw error;
        if (options.signal?.aborted) throw new SellAppCancellationError('Request cancelled', { cause: error });
        if (error instanceof DOMException && error.name === 'AbortError') {
          throw new SellAppTimeoutError(`Request timed out: ${method} ${path}`, { cause: error });
        }
        if (retryable && attempt < maxRetries) {
          this.options.onRequest?.({ operationId: options.operationId, attempt: attempt + 1, durationMs: Date.now() - startedAt, errorType: 'transport' });
          clearTimeout(timeout);
          await waitForRetry(retryDelay(null, attempt), options.signal);
          continue;
        }
        this.options.onRequest?.({ operationId: options.operationId, attempt: attempt + 1, durationMs: Date.now() - startedAt, errorType: 'transport' });
        throw new SellAppTransportError(`Request failed: ${method} ${path}`, { cause: error });
      } finally {
        clearTimeout(timeout);
        options.signal?.removeEventListener('abort', abort);
      }
    }
  }
}
